import sys
p = sys.argv[1]; s = open(p, encoding='utf8').read()
rep = {}
def R(start, new):
    i = s.find(start)
    assert i >= 0, start[:40]
    j = s.find('\n', i)
    rep[s[i:j]] = new
R("โดย $n$ รอบต่อวินาที (rev/s)", "โดย $n$ รอบต่อวินาที, $D$ เส้นผ่านศูนย์กลาง (m), $\\rho$ ความหนาแน่น (kg/m³) มีตัวคูณ Mach, ความเร็วเหนี่ยวนำ, แรงบิดปฏิกิริยา $-\\text{sense}\\cdot P/\\omega$ และโมเมนต์ไจโรสโคปจาก $I_{xx}\\omega$ ส่วน P-factor ทำโดย **เลื่อนจุดที่แรงขับกระทำ** ไปด้านข้างตามมุมของกระแสลมผ่านจานใบพัด [S4] ซึ่งง่ายและเหมาะกับเรา (ดูหัวข้อ 3)")
