for a, b in rep.items():
    assert s.count(a) == 1, a[:50]
    s = s.replace(a, b)
import re
s = re.sub(r'\n\n\n+', '\n\n', s)
open(p, 'w', encoding='utf8').write(s)
print(len(s), len(s.encode()))
